import type { Metadata } from "next";

export const SITE_URL = "https://josepaulotimbang.com";
export const SITE_NAME = "Jose Paulo Timbang";
export const SITE_TITLE = "Jose Paulo Timbang — Full-Stack & AI Developer";
export const HOME_DESCRIPTION =
  "Full-Stack & AI Developer in Ottawa with 8 years of experience building web apps and AI-powered platforms with React, Next.js, Python, PHP and LLM APIs.";

/** Link-preview image, generated by app/og.png/route.tsx. */
export const OG_IMAGE = {
  url: "/og.png",
  width: 1200,
  height: 630,
  alt: SITE_TITLE,
  type: "image/png",
};

/**
 * Page URL as the live site serves it. next.config uses trailingSlash: true,
 * so /about redirects to /about/ — canonicals, og:url and the sitemap must
 * all use the slash form.
 */
export function pagePath(path: string): string {
  if (path === "" || path === "/") return "/";
  return `/${path.replace(/^\/+|\/+$/g, "")}/`;
}

export function absoluteUrl(path: string): string {
  return SITE_URL + pagePath(path);
}

type PageMetaInput = {
  /** Short title; the layout template adds " | Jose Paulo Timbang". */
  title: string;
  description: string;
  path: string;
  /** Title for link previews, if different from "<title> | Jose Paulo Timbang". */
  socialTitle?: string;
  article?: { publishedTime: string; tags?: string[] };
};

/**
 * Per-page metadata: canonical URL plus Open Graph / Twitter tags that point
 * at this page. Next.js merges metadata shallowly, so a page without its own
 * openGraph would otherwise show the home page's title and URL when shared.
 * Every page also gets the shared preview image (OG_IMAGE).
 */
export function pageMetadata({ title, description, path, socialTitle, article }: PageMetaInput): Metadata {
  const url = pagePath(path);
  const shareTitle = socialTitle ?? `${title} | ${SITE_NAME}`;

  return {
    title,
    description,
    alternates: { canonical: url },
    openGraph: {
      siteName: SITE_NAME,
      locale: "en_US",
      url,
      title: shareTitle,
      description,
      images: [OG_IMAGE],
      ...(article
        ? { type: "article", publishedTime: article.publishedTime, authors: [SITE_URL + "/"], tags: article.tags }
        : { type: "website" }),
    },
    twitter: {
      card: "summary_large_image",
      title: shareTitle,
      description,
      images: [OG_IMAGE.url],
    },
  };
}
